# DATABASE
# ============================================================
def get_conn():
    conn = sqlite3.connect(DB_PATH, timeout=30, check_same_thread=False)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    return conn


def column_exists(conn, table, column):
    return any(r[1] == column for r in conn.execute(f"PRAGMA table_info({table})").fetchall())


def add_column_if_missing(conn, table, column, definition):
    if not column_exists(conn, table, column):
        conn.execute(f"ALTER TABLE {table} ADD COLUMN {column} {definition}")


def hash_password(password):
    return hashlib.sha256(str(password).encode("utf-8")).hexdigest()


def init_db():
    # IMPORTANT: all statements use this same live connection; no cursor survives conn.close().
    conn = get_conn()
    try:
        conn.executescript(
            """
            CREATE TABLE IF NOT EXISTS users(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                email TEXT UNIQUE NOT NULL,
                phone TEXT DEFAULT '',
                password_hash TEXT NOT NULL,
                role TEXT DEFAULT 'user',
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
            CREATE TABLE IF NOT EXISTS hotels(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                source TEXT DEFAULT 'StayNest', source_id TEXT DEFAULT '',
                name TEXT NOT NULL, city TEXT NOT NULL, state TEXT DEFAULT '', country TEXT DEFAULT 'India',
                address TEXT DEFAULT '', latitude REAL DEFAULT 0, longitude REAL DEFAULT 0,
                property_type TEXT DEFAULT 'Hotel', display_type TEXT DEFAULT 'Hotel',
                star_rating REAL DEFAULT 3, review_rating REAL DEFAULT 0, review_count INTEGER DEFAULT 0,
                description TEXT DEFAULT '', facilities TEXT DEFAULT '', website TEXT DEFAULT '',
                image_url TEXT DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(name,city)
            );
            CREATE TABLE IF NOT EXISTS rooms(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                hotel_id INTEGER NOT NULL, room_type TEXT NOT NULL,
                price_per_night REAL DEFAULT 2500, total_rooms INTEGER DEFAULT 5,
                available_rooms INTEGER DEFAULT 5, room_facilities TEXT DEFAULT '',
                FOREIGN KEY(hotel_id) REFERENCES hotels(id) ON DELETE CASCADE
            );
            CREATE TABLE IF NOT EXISTS bookings(
                id INTEGER PRIMARY KEY AUTOINCREMENT, booking_code TEXT UNIQUE NOT NULL,
                user_id INTEGER NOT NULL, hotel_id INTEGER NOT NULL, room_id INTEGER NOT NULL,
                check_in TEXT NOT NULL, check_out TEXT NOT NULL, guests INTEGER DEFAULT 1,
                nights INTEGER DEFAULT 1, rooms_count INTEGER DEFAULT 1, amount REAL DEFAULT 0,
                subtotal REAL DEFAULT 0, discount_amount REAL DEFAULT 0, tax_amount REAL DEFAULT 0,
                status TEXT DEFAULT 'Confirmed', payment_method TEXT DEFAULT 'UPI', payment_status TEXT DEFAULT 'Paid',
                guest_name TEXT DEFAULT '', guest_email TEXT DEFAULT '', guest_phone TEXT DEFAULT '',
                special_request TEXT DEFAULT '', promo_code TEXT DEFAULT '', qr_token TEXT DEFAULT '',
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(hotel_id) REFERENCES hotels(id), FOREIGN KEY(room_id) REFERENCES rooms(id)
            );
            CREATE TABLE IF NOT EXISTS reviews(
                id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, hotel_id INTEGER NOT NULL,
                rating REAL NOT NULL, comment TEXT DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(user_id,hotel_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(hotel_id) REFERENCES hotels(id)
            );
            CREATE TABLE IF NOT EXISTS wishlist(
                id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, hotel_id INTEGER NOT NULL,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,hotel_id)
            );
            CREATE TABLE IF NOT EXISTS promo_codes(
                id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT UNIQUE NOT NULL, discount_type TEXT NOT NULL,
                discount_value REAL NOT NULL, min_amount REAL DEFAULT 0, max_discount REAL DEFAULT 0,
                active INTEGER DEFAULT 1, valid_from TEXT DEFAULT '', valid_until TEXT DEFAULT '', usage_limit INTEGER DEFAULT 0, used_count INTEGER DEFAULT 0
            );
            CREATE TABLE IF NOT EXISTS notifications(
                id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, audience TEXT DEFAULT 'user',
                title TEXT NOT NULL, message TEXT NOT NULL, booking_code TEXT DEFAULT '', is_read INTEGER DEFAULT 0,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
            """
        )

        # Upgrade old databases safely.
        upgrades = [
            ("hotels", "display_type", "TEXT DEFAULT 'Hotel'"),
            ("hotels", "image_url", "TEXT DEFAULT ''"),
            ("hotels", "rooms_seeded", "INTEGER DEFAULT 0"),
            ("bookings", "rooms_count", "INTEGER DEFAULT 1"),
            ("bookings", "subtotal", "REAL DEFAULT 0"),
            ("bookings", "discount_amount", "REAL DEFAULT 0"),
            ("bookings", "tax_amount", "REAL DEFAULT 0"),
            ("bookings", "payment_method", "TEXT DEFAULT 'UPI'"),
            ("bookings", "guest_name", "TEXT DEFAULT ''"),
            ("bookings", "guest_email", "TEXT DEFAULT ''"),
            ("bookings", "guest_phone", "TEXT DEFAULT ''"),
            ("bookings", "special_request", "TEXT DEFAULT ''"),
            ("bookings", "promo_code", "TEXT DEFAULT ''"),
            ("bookings", "qr_token", "TEXT DEFAULT ''"),
        ]
        for table, col, definition in upgrades:
            try:
                add_column_if_missing(conn, table, col, definition)
            except sqlite3.OperationalError:
                pass

        # Seed promo codes only if absent. Promo codes are not forced on every booking.
        promo_seed = [
            ("STAYNEST10", "percent", 10, 0, 0),
            ("STAY500", "flat", 500, 5000, 500),
            ("WEEKEND15", "percent", 15, 7000, 1500),
        ]
        for row in promo_seed:
            conn.execute(
                "INSERT OR IGNORE INTO promo_codes(code,discount_type,discount_value,min_amount,max_discount,active) VALUES(?,?,?,?,?,1)", row
            )

        # Admin is created from environment variables/defaults, but credentials are NEVER shown in the guest UI.
        conn.execute(
            "INSERT OR IGNORE INTO users(name,email,phone,password_hash,role) VALUES(?,?,?,?,?)",
            ("StayNest Administrator", ADMIN_EMAIL, "", hash_password(ADMIN_PASSWORD), "admin"),
        )
        conn.commit()
    finally:
        conn.close()


def execute(sql, params=()):
    conn = get_conn()
    try:
        cur = conn.execute(sql, params)
        conn.commit()
        return cur.lastrowid
    finally:
        conn.close()


def fetch_one(sql, params=()):
    conn = get_conn()
    try:
        row = conn.execute(sql, params).fetchone()
        return dict(row) if row else None
    finally:
        conn.close()


def fetch_all(sql, params=()):
    conn = get_conn()
    try:
        return [dict(r) for r in conn.execute(sql, params).fetchall()]
    finally:
        conn.close()


def query_df(sql, params=()):
    conn = get_conn()
    try:
        return pd.read_sql_query(sql, conn, params=params)
    finally:
        conn.close()

