def clean_text(v, default=""):
    if v is None:
        return default
    try:
        if pd.isna(v):
            return default
    except Exception:
        pass
    s = str(v).strip()
    return s if s and s.lower() not in {"nan", "none", "null"} else default


def to_float(v, default=0.0):
    try:
        nums = re.findall(r"-?\d+(?:\.\d+)?", clean_text(v))
        return float(nums[0]) if nums else default
    except Exception:
        return default


def to_int(v, default=0):
    try:
        return int(round(to_float(v, default)))
    except Exception:
        return default


def normalize_type(raw, name="", desc="", facilities=""):
    text = " ".join([clean_text(raw), clean_text(name), clean_text(desc), clean_text(facilities)]).lower()
    rules = [
        (["tent", "camping", "glamping", "campsite"], "Tent / Glamping"),
        (["villa"], "Villa"), (["resort"], "Resort"),
        (["guest house", "guesthouse"], "Guest House"), (["hostel", "backpacker", "dormitory"], "Hostel"),
        (["homestay", "home stay"], "Homestay"), (["farm stay", "farmhouse"], "Farm Stay"),
        (["apartment", "flat"], "Apartment"), (["bed and breakfast", "b&b"], "Bed & Breakfast"),
        (["motel"], "Motel"), (["lodge"], "Lodge"), (["holiday home"], "Holiday Home"),
    ]
    for keys, label in rules:
        if any(k in text for k in keys):
            return label
    raw_s = clean_text(raw)
    if raw_s and not re.fullmatch(r"\d+(?:\.0+)?", raw_s):
        title = raw_s.title()
        allowed = {"Hotel","Resort","Villa","Hostel","Guest House","Apartment","Motel","Lodge","Homestay","Farm Stay","Holiday Home"}
        if title in allowed:
            return title
    return "Hotel"


