def image_for_type(ptype, index=0):
    sets = IMAGE_SETS
    arr = sets.get(ptype, sets["Hotel"])
    return arr[index % len(arr)]


def demo_price(city, stars, room_type, ptype):
    factors = {"mumbai":1.25,"new delhi":1.2,"delhi":1.2,"bangalore":1.1,"bengaluru":1.1,"goa":1.2,"jaipur":1.05,"udaipur":1.12,"ahmedabad":1.0,"pune":1.05,"hyderabad":1.0,"chennai":1.0,"kolkata":.95,"manali":1.12,"srinagar":1.1}
    base = 1700 + max(0,min(float(stars or 0),5))*550
    r = clean_text(room_type).lower(); p = clean_text(ptype).lower()
    if any(x in r for x in ["suite","premium","executive"]): base += 1800
    elif any(x in r for x in ["deluxe","superior"]): base += 850
    elif any(x in r for x in ["family","triple"]): base += 650
    if "resort" in p: base += 700
    if "villa" in p: base += 1000
    return round(base * factors.get(clean_text(city).lower(),1.0) / 100) * 100


