def import_catalog_files():
    # Import only when the database has no hotels. This keeps admin edits persistent.
    if fetch_one("SELECT COUNT(*) c FROM hotels")["c"] > 0:
        return
    found = False
    for path in CATALOG_FILES:
        if not path.exists():
            continue
        try:
            df = pd.read_csv(path)
        except Exception:
            continue
        found = True
        for _, r in df.head(2500).iterrows():
            name = clean_text(r.get("property_name"))
            city = clean_text(r.get("city"), "Unknown")
            if not name:
                continue
            ptype = normalize_type(r.get("property_type"),name,clean_text(r.get("hotel_description")),clean_text(r.get("hotel_facilities")))
            rating = to_float(r.get("site_review_rating"))
            if rating > 5 and rating <= 10: rating = round(rating/2,2)
            try:
                hid = execute("""INSERT OR IGNORE INTO hotels(source,source_id,name,city,state,country,address,latitude,longitude,property_type,display_type,star_rating,review_rating,review_count,description,facilities,website,image_url) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""", (
                    path.stem, clean_text(r.get("property_id")), name, city, clean_text(r.get("state")), clean_text(r.get("country"),"India"), clean_text(r.get("address")), to_float(r.get("latitude")), to_float(r.get("longitude")), ptype, ptype, to_float(r.get("hotel_star_rating")), rating, to_int(r.get("site_review_count")), clean_text(r.get("hotel_description")), clean_text(r.get("hotel_facilities")), clean_text(r.get("pageurl")), image_for_type(ptype,0)))
                if not hid:
                    h = fetch_one("SELECT id FROM hotels WHERE name=? AND city=?",(name,city)); hid = h["id"] if h else None
                if hid:
                    exists = fetch_one("SELECT id FROM rooms WHERE hotel_id=? LIMIT 1",(hid,))
                    if not exists:
                        rt = clean_text(r.get("room_type"),"Standard Room")
                        total = max(to_int(r.get("room_count"),5),1)
                        price = demo_price(city,to_float(r.get("hotel_star_rating")),rt,ptype)
                        execute("INSERT INTO rooms(hotel_id,room_type,price_per_night,total_rooms,available_rooms,room_facilities) VALUES(?,?,?,?,?,?)",(hid,rt,price,total,total,clean_text(r.get("room_facilities")) or clean_text(r.get("hotel_facilities"))))
            except sqlite3.IntegrityError:
                pass
    if not found:
        seed_demo_catalog()

