def ensure_room_categories():
    """Give every imported/demo hotel a complete set of room categories exactly once.
    Admin-managed hotels and rooms deleted later by the admin are never re-created."""
    conn = get_conn()
    try:
        conn.execute("UPDATE hotels SET rooms_seeded=1 WHERE source='Admin' AND rooms_seeded=0")
        hotels = conn.execute("SELECT id,city,star_rating,display_type,property_type FROM hotels WHERE rooms_seeded=0").fetchall()
        for h in hotels:
            ptype = h["display_type"] or h["property_type"] or "Hotel"
            bps = ROOM_BLUEPRINTS.get(ptype, ROOM_BLUEPRINTS["default"])
            existing = conn.execute("SELECT room_type,price_per_night FROM rooms WHERE hotel_id=?", (h["id"],)).fetchall()
            covered, base = set(), None
            for bp in bps:
                for e in existing:
                    nm = (e["room_type"] or "").lower()
                    if bp[4] in nm:
                        covered.add(bp[4])
                        if base is None:
                            base = float(e["price_per_night"] or 0) / bp[1]
            if existing and not covered:
                base = min(float(e["price_per_night"] or 0) for e in existing)
                covered.add("standard")
            if not base or base <= 0:
                base = demo_price(h["city"], h["star_rating"], "Standard Room", ptype)
            base = min(max(base, 800), 60000)
            for bp in bps:
                if bp[4] in covered:
                    continue
                price = max(round(base * bp[1] / 100) * 100, 500)
                total = bp[2] + (int(h["id"]) % 3)
                conn.execute("INSERT INTO rooms(hotel_id,room_type,price_per_night,total_rooms,available_rooms,room_facilities) VALUES(?,?,?,?,?,?)",
                             (h["id"], bp[0], price, total, total, bp[3]))
            conn.execute("UPDATE hotels SET rooms_seeded=1 WHERE id=?", (h["id"],))
        conn.commit()
    finally:
        conn.close()

