def init_trip():
    if "trip" not in st.session_state:
        st.session_state.trip = {"city": "All", "search": "", "property_type": "All",
                                 "check_in": date.today() + timedelta(days=1), "check_out": date.today() + timedelta(days=2),
                                 "guests": 2, "rooms": 1}
    t = st.session_state.trip
    if t["check_in"] < date.today(): t["check_in"] = date.today() + timedelta(days=1)
    if t["check_out"] <= t["check_in"]: t["check_out"] = t["check_in"] + timedelta(days=1)
    return t


def _push_trip(widget_key, field):
    t = st.session_state.trip
    t[field] = st.session_state[widget_key]
    if field == "check_in" and t["check_out"] <= t["check_in"]:
        t["check_out"] = t["check_in"] + timedelta(days=1)


def trip_input(container, kind, label, field, key, **kw):
    """A widget bound to the shared trip value: changing it anywhere updates it everywhere."""
    t = init_trip()
    st.session_state[key] = t[field]
    return getattr(container, kind)(label, key=key, on_change=_push_trip, args=(key, field), **kw)


