def get_public_promo_offers():
    """Return currently usable promo offers for the guest-facing Offers section."""
    today = date.today().isoformat()
    rows = fetch_all("SELECT * FROM promo_codes WHERE active=1 ORDER BY code")
    offers = []
    for promo in rows:
        if promo.get("valid_from") and promo["valid_from"] > today:
            continue
        if promo.get("valid_until") and promo["valid_until"] < today:
            continue
        limit = int(promo.get("usage_limit") or 0)
        if limit > 0 and int(promo.get("used_count") or 0) >= limit:
            continue
        offers.append(promo)
    return offers


def promo_offer_description(promo):
    if promo.get("discount_type") == "percent":
        discount = f"{float(promo.get('discount_value') or 0):g}% off"
        if float(promo.get("max_discount") or 0) > 0:
            discount += f" · up to ₹{int(promo['max_discount']):,} off"
    else:
        discount = f"₹{int(float(promo.get('discount_value') or 0)):,} off"
    minimum = float(promo.get("min_amount") or 0)
    condition = f"Minimum booking ₹{int(minimum):,}" if minimum > 0 else "No minimum booking amount"
    expiry = promo.get("valid_until")
    if expiry:
        condition += f" · Valid until {expiry}"
    return discount, condition


def stars_html(v):
    n=max(0,min(5,int(round(to_float(v)))))
    return "★"*n+"☆"*(5-n)


def hotel_cover(hotel):
    """Stored default photos are re-picked per hotel so cards look varied and always use the current photo set."""
    p=hotel.get("display_type") or hotel.get("property_type") or "Hotel"
    url=clean_text(hotel.get("image_url"))
    if not url or url in DEFAULT_IMAGE_URLS:
        return image_for_type(p,int(hotel.get("id") or 0))
    return url


def hotel_images(hotel):
    p=hotel.get("display_type") or hotel.get("property_type") or "Hotel"
    hid=int(hotel.get("id") or 0); cover=hotel_cover(hotel)
    if cover in DEFAULT_IMAGE_URLS: return [image_for_type(p,hid+k) for k in range(3)]
    return [cover,image_for_type(p,hid),image_for_type(p,hid+1)]


