def booked_count(room_id, ci, co):
    r=fetch_one("""SELECT COALESCE(SUM(rooms_count),0) booked FROM bookings WHERE room_id=? AND status IN ('Confirmed','Checked-in') AND date(check_in)<date(?) AND date(check_out)>date(?)""",(room_id,str(co),str(ci)))
    return int(r["booked"] or 0)


def available(room, ci=None, co=None):
    total=int(room.get("total_rooms") or 0)
    if not ci or not co: return total
    return max(total-booked_count(room["id"],ci,co),0)


def calculate_nights(ci,co): return max((co-ci).days,1)


def search_hotels(search="",city="All",ptype="All",min_rating=0,max_price=100000,sort="Recommended"):
    sql="""SELECT h.*,COALESCE(MIN(r.price_per_night),0) min_price FROM hotels h LEFT JOIN rooms r ON r.hotel_id=h.id WHERE 1=1"""; params=[]
    if search:
        q=f"%{search.lower()}%"; sql += " AND (LOWER(h.name) LIKE ? OR LOWER(h.city) LIKE ? OR LOWER(h.state) LIKE ? OR LOWER(h.property_type) LIKE ? OR LOWER(h.facilities) LIKE ? OR LOWER(h.description) LIKE ?)"; params += [q]*6
    if city!="All": sql += " AND LOWER(h.city)=LOWER(?)"; params.append(city)
    if ptype!="All": sql += " AND LOWER(COALESCE(h.display_type,h.property_type))=LOWER(?)"; params.append(ptype)
    if min_rating: sql += " AND COALESCE(h.review_rating,0)>=?"; params.append(min_rating)
    sql += " GROUP BY h.id HAVING min_price<=?"; params.append(max_price)
    order={"Price: Low to High":"min_price ASC","Price: High to Low":"min_price DESC","Rating":"review_rating DESC,review_count DESC"}.get(sort,"review_rating DESC,review_count DESC")
    sql += f" ORDER BY {order} LIMIT 100"
    return query_df(sql,params)


def show_hotel_card(hotel,ci=None,co=None):
    ptype=hotel.get("display_type") or hotel.get("property_type") or "Hotel"; img=hotel_cover(hotel)
    rating=to_float(hotel.get("review_rating")); rating_text=f"{rating:.1f}/5" if rating else "New"
    avail=sum(available(r,ci,co) for r in fetch_all("SELECT * FROM rooms WHERE hotel_id=?",(hotel["id"],)))
    st.markdown(f"""
    <div class='hotel-card'><div class='hotel-img' style="background-image:url('{img}')"><span class='badge'>✦ {ptype}</span></div>
    <div class='hotel-body'><div class='hotel-name'>{clean_text(hotel.get('name'))}</div>
    <div class='hotel-location'>📍 {clean_text(hotel.get('city')).title()}, {clean_text(hotel.get('state'))}</div>
    <span class='rating'>★ {rating_text}</span><span class='subtle' style='margin-left:10px'>{int(hotel.get('review_count') or 0):,} reviews</span>
    <div style='display:flex;justify-content:space-between;align-items:end;margin-top:15px'><div><span class='hotel-price'>₹{int(hotel.get('min_price') or 0):,}</span><span class='subtle'> / night</span></div><span class='subtle'>{avail} room(s) available</span></div></div></div>
    """,unsafe_allow_html=True)

