    cities=["All"]+sorted([x["city"] for x in fetch_all("SELECT DISTINCT city FROM hotels WHERE city<>'' ORDER BY city")])
    types=["All","Hotel","Resort","Villa","Guest House","Hostel","Tent / Glamping","Apartment","Farm Stay","Lodge","Motel","Homestay","Bed & Breakfast"]
    if t["city"] not in cities: t["city"]="All"
    if t["property_type"] not in types: t["property_type"]="All"
    a,b,c,d=st.columns([1.8,1.2,1,1.2])
    search=trip_input(a,"text_input","Search","search","hotels_search",placeholder="Hotel, area, landmark...")
    city=trip_input(b,"selectbox","City","city","hotels_city",options=cities)
    rating=c.selectbox("Guest rating",[0,3,3.5,4,4.5],format_func=lambda x:"Any" if x==0 else f"{x}+ ⭐")
    sort=d.selectbox("Sort by",["Recommended","Price: Low to High","Price: High to Low","Rating"])
    e,f,g,h=st.columns([1.1,1.1,1.2,1.2])
    ci=trip_input(e,"date_input","Check-in","check_in","hotels_ci",min_value=date.today())
    co=trip_input(f,"date_input","Check-out","check_out","hotels_co",min_value=date.today()+timedelta(days=1))
    max_price=g.number_input("Max / night",500,200000,30000,500)
    ptype=trip_input(h,"selectbox","Stay type","property_type","hotels_type",options=types)
    if co<=ci: st.error("Check-out must be after check-in."); return
    hotels=search_hotels(search,city,ptype,rating,max_price,sort)
    visible=[]
    for _,hrow in hotels.iterrows():
        if sum(available(r,ci,co) for r in fetch_all("SELECT * FROM rooms WHERE hotel_id=?",(int(hrow["id"]),)))>0: visible.append(hrow)
    st.caption(f"{len(visible)} stay(s) available for {ci} → {co}")
    if not visible: st.warning("No available stays match these filters."); return
    for start in range(0,len(visible),3):
        cols=st.columns(3)
        for col,hrow in zip(cols,visible[start:start+3]):
            with col:
                show_hotel_card(hrow,ci,co)
                x,y=st.columns(2)
                if x.button("View rooms",key=f"hotel_{int(hrow['id'])}",type="primary",use_container_width=True):
                    st.session_state.selected_hotel=int(hrow["id"]); st.session_state.detail_dates={"check_in":ci,"check_out":co,"guests":2}; go("Hotel Details")
                if y.button("♡ Save",key=f"save_{int(hrow['id'])}",use_container_width=True):
                    if not current_user(): st.session_state.auth_return="Hotels"; go("Login")
                    elif current_user().get("role")=="admin": st.info("Admin accounts do not use the guest wishlist.")
                    else:
                        uid=current_user()["id"]
                        if fetch_one("SELECT id FROM wishlist WHERE user_id=? AND hotel_id=?",(uid,int(hrow["id"]))): execute("DELETE FROM wishlist WHERE user_id=? AND hotel_id=?",(uid,int(hrow["id"]))); st.success("Removed from saved stays.")
                        else: execute("INSERT INTO wishlist(user_id,hotel_id) VALUES(?,?)",(uid,int(hrow["id"]))); st.success("Saved.")


