def render_small_map(hotel, hid):
    lat, lon = to_float(hotel.get("latitude")), to_float(hotel.get("longitude"))
    st.markdown("<div class='map-card'><div class='t'>📍 Location</div>", unsafe_allow_html=True)
    if lat and lon:
        try:
            import folium
            from streamlit_folium import st_folium
            fmap = folium.Map(location=[lat, lon], zoom_start=14, control_scale=False)
            folium.Marker([lat, lon], tooltip=clean_text(hotel.get("name")), popup=clean_text(hotel.get("address")) or f"{hotel.get('city')}, India", icon=folium.Icon(color="black", icon="home")).add_to(fmap)
            st_folium(fmap, use_container_width=True, height=250, key=f"hotel_map_{hid}", returned_objects=[])
        except Exception:
            st.caption("Interactive map is unavailable here.")
        st.link_button("Open in Google Maps", f"https://www.google.com/maps/search/?api=1&query={lat},{lon}", use_container_width=True)
        if clean_text(hotel.get("source")) == "StayNest Demo":
            st.caption("Approximate city-centre marker. Admin can set exact latitude/longitude.")
    else:
        st.info("Exact map coordinates are not available for this property.")
        st.link_button("Find on Google Maps", f"https://www.google.com/maps/search/?api=1&query={clean_text(hotel.get('name'))}%20{clean_text(hotel.get('city'))}", use_container_width=True)
    st.markdown("</div>", unsafe_allow_html=True)


