def promo_discount(code,subtotal):
    code=clean_text(code).upper()
    if not code: return 0,"No promo applied",None
    p=fetch_one("SELECT * FROM promo_codes WHERE code=? AND active=1",(code,))
    if not p: return 0,"Invalid promo code",None
    today=date.today().isoformat()
    if p.get("valid_from") and today<p["valid_from"]: return 0,"Promo is not active yet",None
    if p.get("valid_until") and today>p["valid_until"]: return 0,"Promo has expired",None
    if int(p.get("usage_limit") or 0)>0 and int(p.get("used_count") or 0)>=int(p["usage_limit"]): return 0,"Promo usage limit reached",None
    if subtotal<float(p.get("min_amount") or 0): return 0,f"Minimum booking value is ₹{int(p['min_amount']):,}",None
    if p["discount_type"]=="percent":
        disc=subtotal*float(p["discount_value"])/100
        if float(p.get("max_discount") or 0)>0: disc=min(disc,float(p["max_discount"]))
        return round(disc,2),f"{p['discount_value']:g}% off",p
    return min(round(float(p["discount_value"]),2),subtotal),f"₹{int(p['discount_value']):,} off",p


