            st.markdown(f"**Selected room:** {clean_text(room['room_type'])} · ₹{int(room['price_per_night']):,}/night")
            c1,c2,c3=st.columns(3); ci=c1.date_input("Check-in",ci0,min_value=date.today()); co=c2.date_input("Check-out",co0,min_value=date.today()+timedelta(days=1)); guests=c3.number_input("Guests",1,20,g0)
            av=available(room,ci,co) if co>ci else 0
