            available_offers = get_public_promo_offers()
            offer_labels = {"Enter code manually": ""}
            for offer in available_offers:
                discount_text, condition_text = promo_offer_description(offer)
                offer_labels[f"{offer['code']} · {discount_text} · {condition_text}"] = offer["code"]
            chosen_offer = st.selectbox("Available offers", list(offer_labels.keys()), help="Choose an active offer shown on the StayNest home page, or enter a code below.")
            manual_promo = st.text_input("Or enter promo code manually (optional)",placeholder="Enter promo code")
