def add_notification(audience,title,message,booking_code="",user_id=None):
    execute("INSERT INTO notifications(user_id,audience,title,message,booking_code) VALUES(?,?,?,?,?)",(user_id,audience,title,message,booking_code))


def confirm_booking(p):
    conn=get_conn()
    try:
        conn.execute("BEGIN")
        room=conn.execute("SELECT * FROM rooms WHERE id=?",(p["room_id"],)).fetchone()
        if not room: raise ValueError("Room no longer exists.")
        booked=conn.execute("SELECT COALESCE(SUM(rooms_count),0) b FROM bookings WHERE room_id=? AND status IN ('Confirmed','Checked-in') AND date(check_in)<date(?) AND date(check_out)>date(?)",(p["room_id"],str(p["check_out"]),str(p["check_in"]))).fetchone()["b"]
        av=int(room["total_rooms"])-int(booked or 0)
        if av<int(p["rooms_count"]): raise ValueError(f"Only {av} room(s) are available for these dates.")
        code="NVS"+datetime.now().strftime("%y%m%d%H%M%S")+secrets.token_hex(2).upper(); token=secrets.token_urlsafe(22)
        pay_status="Paid" if p["payment"]!="Pay at Hotel" else "Pay at Hotel"
        conn.execute("""INSERT INTO bookings(booking_code,user_id,hotel_id,room_id,check_in,check_out,guests,nights,rooms_count,amount,subtotal,discount_amount,tax_amount,status,payment_method,payment_status,guest_name,guest_email,guest_phone,special_request,promo_code,qr_token) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",(code,current_user()["id"],p["hotel_id"],p["room_id"],str(p["check_in"]),str(p["check_out"]),p["guests"],p["nights"],p["rooms_count"],p["total"],p["subtotal"],p["discount"],p["tax"],"Confirmed",p["payment"],pay_status,p["name"],p["email"],p["phone"],p["special"],p["promo"],token))
        if p["promo"] and p["discount"]>0: conn.execute("UPDATE promo_codes SET used_count=used_count+1 WHERE code=?",(p["promo"],))
        conn.commit()
        add_notification(current_user()["id"],"Booking confirmed",f"{p['name']}, your reservation {code} is confirmed.",code,current_user()["id"])
        add_notification(None,"New booking received",f"Booking {code}: guest {p['name']} · {p['email']} · {p['phone']} · {p['rooms_count']} room(s).",code,None)
        st.session_state.last_booking_code=code; st.session_state.pending_booking=None; st.session_state.selected_room=None; go("Booking Confirmation")
    except Exception as e:
        conn.rollback(); st.error(str(e))
    finally: conn.close()


def make_qr_bytes(value):
    if qrcode is None: return None
    img=qrcode.make(value); buf=io.BytesIO(); img.save(buf,format="PNG"); return buf.getvalue()


