def decode_qr(uploaded):
    if uploaded is None or cv2 is None or np is None: return None
    try:
        arr=np.frombuffer(uploaded.getvalue(),dtype=np.uint8); img=cv2.imdecode(arr,cv2.IMREAD_COLOR); value,_,_=cv2.QRCodeDetector().detectAndDecode(img); return value.strip() if value else None
    except Exception: return None


def scanner_page():
    st.markdown("<div class='section-title'>StayNest QR Verification</div>",unsafe_allow_html=True)
    user=current_user()
    if not user: st.info("Sign in to use the booking QR scanner."); return
    if user.get("role")=="admin": st.markdown("<div class='card'><b>Admin scanner:</b> upload the exact QR image downloaded from a StayNest booking. The result includes the reservation and guest contact details.</div>",unsafe_allow_html=True)
    else: st.markdown("<div class='card'><b>Guest scanner:</b> upload the exact QR image from your booking. The result shows your reservation details without exposing other guests.</div>",unsafe_allow_html=True)
    if cv2 is None: st.warning("QR image decoding requires opencv-python. Install it with: pip install opencv-python")
    source=st.radio("Scanner input",["Upload QR image","Use camera"],horizontal=True)
    uploaded=st.file_uploader("Upload the same StayNest QR PNG you downloaded",type=["png","jpg","jpeg"]) if source=="Upload QR image" else st.camera_input("Scan your StayNest QR")
    if uploaded:
        value=decode_qr(uploaded)
        if not value: st.error("QR could not be read. Upload the downloaded StayNest PNG clearly; do not upload a hotel photo."); return
        b=fetch_one("""SELECT b.*,h.name hotel_name,h.city,h.state,h.address,h.property_type,r.room_type,u.name user_name,u.email user_email,u.phone user_phone FROM bookings b JOIN hotels h ON h.id=b.hotel_id JOIN rooms r ON r.id=b.room_id JOIN users u ON u.id=b.user_id WHERE b.qr_token=? OR b.booking_code=?""",(value,value))
        if not b: st.error("This QR does not belong to a StayNest booking."); return
        if user.get("role")=="user" and int(b["user_id"])!=int(user["id"]): st.error("This booking QR belongs to another guest account."); return
        st.success(f"Booking verified · {b['booking_code']}")
        if user.get("role")=="admin":
            st.markdown(f"<div class='success'><h3>Admin verification view</h3><p><b>Guest:</b> {clean_text(b['user_name'])}</p><p><b>Email:</b> {clean_text(b['user_email'])}</p><p><b>Phone:</b> {clean_text(b['user_phone'])}</p><p><b>Hotel:</b> {clean_text(b['hotel_name'])}</p><p><b>Room:</b> {clean_text(b['room_type'])} × {b['rooms_count']}</p><p><b>Dates:</b> {b['check_in']} → {b['check_out']}</p><p><b>Guests:</b> {b['guests']}</p><p><b>Total:</b> ₹{int(b['amount']):,}</p><p><b>Status:</b> {b['status']}</p></div>",unsafe_allow_html=True)
