def recommendations_page():
    st.markdown("<div class='section-title'>Smart Recommendations ✦</div>",unsafe_allow_html=True)
    cities=["Any"]+sorted([x["city"] for x in fetch_all("SELECT DISTINCT city FROM hotels WHERE city<>'' ORDER BY city")]); amenities=["Any","WiFi","Parking","Pool","Restaurant","Gym","Room Service","Breakfast"]
    a,b,c=st.columns(3); city=a.selectbox("Preferred destination",cities); budget=b.number_input("Maximum nightly budget",500,100000,7000,500); amenity=c.selectbox("Preferred amenity",amenities)
    hotels=query_df("SELECT h.*,COALESCE(MIN(r.price_per_night),0) min_price FROM hotels h LEFT JOIN rooms r ON r.hotel_id=h.id GROUP BY h.id HAVING min_price<=?",(budget,))
    if city!="Any": hotels=hotels[hotels["city"].str.lower()==city.lower()]
    if amenity!="Any": hotels=hotels[hotels["facilities"].fillna("").str.contains(amenity,case=False,na=False)]
    if hotels.empty: st.warning("No hotels match those preferences."); return
    query=" ".join([x for x in [city if city!="Any" else "",amenity if amenity!="Any" else ""] if x])
    if SKLEARN_OK and query.strip() and len(hotels)>1:
        corpus=(hotels["name"].fillna("")+" "+hotels["city"].fillna("")+" "+hotels["property_type"].fillna("")+" "+hotels["facilities"].fillna("")+" "+hotels["description"].fillna("")).tolist(); mat=TfidfVectorizer(stop_words="english").fit_transform(corpus+[query]); scores=cosine_similarity(mat[-1],mat[:-1]).flatten(); hotels=hotels.copy(); hotels["smart_score"]=scores; hotels=hotels.sort_values(["smart_score","review_rating"],ascending=False)
    else: hotels=hotels.sort_values(["review_rating","review_count"],ascending=False)
    st.success("Recommendations are based on your selected destination, budget, amenity and hotel content. They are not a guarantee of future availability.")
    for _,h in hotels.head(9).iterrows():
        show_hotel_card(h)
        if st.button("View rooms",key=f"rec_{h['id']}",type="primary"): st.session_state.selected_hotel=int(h["id"]); st.session_state.detail_dates={"check_in":date.today()+timedelta(days=1),"check_out":date.today()+timedelta(days=2),"guests":2}; go("Hotel Details")

